<script lang="ts">
	import type { TreeNode } from '$lib/toc';
	import TocTree from './TocTree.svelte';

	interface Props {
		tree: TreeNode<HTMLElement>;
		[key: string]: any;
	}

	let { tree, ...rest }: Props = $props();

	// Link possibly generated by rehype-slug
	let link = $derived(tree.data.querySelector('a')?.getAttribute('href'));

	// Add styling based on heading level
	let tagName = $derived(tree.data.tagName.toLowerCase());
	let fontClass = $derived(
		tagName === 'h1' || tagName === 'h2'
			? 'font-semibold text-base'
			: tagName === 'h3'
				? 'font-medium text-sm'
				: 'font-light text-sm text-gray-500'
	);
</script>

<div data-testid="toc-tree" class="text-center lg:text-left" {...rest}>
	<p class="mb-1.5 {fontClass}">
		<a class="link-hover link" href={link}>{tree.data.textContent}</a>
	</p>
	<ul>
		{#each tree.children as child (child.data.textContent)}
			<li class="lg:ml-8">
				<TocTree tree={child} />
			</li>
		{/each}
	</ul>
</div>
